// Parse incoming opportunity data
const opp = $input.first().json;

// Calculate score based on reward & skills match
const scoreFactors = {
  reward: (opp.rewardMax || 0) > 1000 ? 30 : 10,
  deadlineUrgent: opp.deadline && new Date(opp.deadline) < new Date(Date.now() + 7*24*60*60*1000) ? 20 : 0,
  skillsMatch: opp.skills && Array.isArray(opp.skills) ? Math.min(30, opp.skills.length * 5) : 0
};

const score = Object.values(scoreFactors).reduce((a,b) => a+b, 0);
const tier = score >= 70 ? 'hot' : score >= 40 ? 'warm' : 'cool';

return {
  ...opp,
  score,
  tier,
  processedAt: new Date().toISOString()
};

